∀ {X : TopCat} {inst : MeasurableSpace ↑X} {inst_1 : BorelSpace ↑X}
  {inst_2 : PhysicsOfConsciousness.TriangulatedManifold ↑X}
  [self : PhysicsOfConsciousness.ThermodynamicCover X]
  (i j : PhysicsOfConsciousness.LocalSectionSynchronization.I X),
  PhysicsOfConsciousness.ThermodynamicCover.A i j = PhysicsOfConsciousness.ThermodynamicCover.A j i

∀ {X : TopCat} {inst : MeasurableSpace ↑X} {inst_1 : BorelSpace ↑X}
  {inst_2 : PhysicsOfConsciousness.TriangulatedManifold ↑X}
  [self : PhysicsOfConsciousness.ThermodynamicCover X]
  (theta : PhysicsOfConsciousness.LocalSectionSynchronization.I X → ℝ),
  PhysicsOfConsciousness.kuramoto_potential_dynamic
      { omega := fun x => 0, A := PhysicsOfConsciousness.ThermodynamicCover.A, symm := ⋯ }
      PhysicsOfConsciousness.LocalSectionSynchronization.phase ≤
    PhysicsOfConsciousness.kuramoto_potential_dynamic
      { omega := fun x => 0, A := PhysicsOfConsciousness.ThermodynamicCover.A, symm := ⋯ } theta

∀ {X : TopCat} {inst : MeasurableSpace ↑X} {inst_1 : BorelSpace ↑X}
  {inst_2 : PhysicsOfConsciousness.TriangulatedManifold ↑X}
  [self : PhysicsOfConsciousness.ThermodynamicCover X]
  (i j : PhysicsOfConsciousness.LocalSectionSynchronization.I X),
  PhysicsOfConsciousness.ThermodynamicCover.A i j > 0

∀ {X : TopCat} {inst : MeasurableSpace ↑X} {inst_1 : BorelSpace ↑X}
  {inst_2 : PhysicsOfConsciousness.TriangulatedManifold ↑X}
  [self : PhysicsOfConsciousness.LocalSectionSynchronization X],
  iSup PhysicsOfConsciousness.LocalSectionSynchronization.cover = ⊤

∀ {sys : Type u_2} {inst : Fintype sys} {inst_1 : DecidableEq sys}
  [self : PhysicsOfConsciousness.BipartiteEnvironment sys] (t : sys → sys),
  Function.Injective (PhysicsOfConsciousness.BipartiteEnvironment.U t)

∀ {sys : Type u_2} {inst : Fintype sys} {inst_1 : DecidableEq sys}
  [self : PhysicsOfConsciousness.BipartiteEnvironment sys] (t : sys → sys),
  (PhysicsOfConsciousness.BipartiteEnvironment.initial_bath t).Nonempty
